import math

def proper_divisors(n):
    if n <= 1:
        return []
    divs = [1]
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    divs.sort()
    return divs

def S(n):
    """Sum of three largest proper divisors of n."""
    pd = proper_divisors(n)
    if len(pd) < 3:
        return None  # doesn't have enough proper divisors
    return sum(pd[-3:])

def check_sequence(a1, max_steps=1000):
    """Check if sequence starting at a1 is valid (infinite). Returns True if it reaches a fixed point or cycle."""
    seen = {}
    a = a1
    for step in range(max_steps):
        pd = proper_divisors(a)
        if len(pd) < 3:
            return False, f"breaks at step {step}: a={a} has only {len(pd)} proper divisors"
        s = sum(pd[-3:])
        if s == a:
            return True, f"fixed point at {a} (step {step})"
        if s in seen:
            return True, f"cycle detected: {s} -> ... (step {step})"
        seen[a] = step
        a = s
    return None, f"no conclusion after {max_steps} steps, last a={a}"

# Check all values from 6 to 2000
valid = []
for n in range(6, 2001):
    result, msg = check_sequence(n, max_steps=200)
    if result:
        valid.append((n, msg))

print(f"Total valid starting values in [6, 2000]: {len(valid)}")
for n, msg in valid[:50]:
    print(f"  a1={n}: {msg}")
if len(valid) > 50:
    print(f"  ... and {len(valid)-50} more")
