import math

def S_fast(n):
    if n <= 5:
        return None
    divs_gt1 = set()
    for d in range(2, int(math.isqrt(n)) + 1):
        if n % d == 0:
            divs_gt1.add(d)
            divs_gt1.add(n // d)
    divs_gt1.add(n)  # n itself is a divisor > 1
    divs_gt1 = sorted(divs_gt1)
    if len(divs_gt1) < 3:
        return None
    d1, d2, d3 = divs_gt1[0], divs_gt1[1], divs_gt1[2]
    return n // d1 + n // d2 + n // d3

def check_seq(a1, max_steps=500):
    a = a1
    for _ in range(max_steps):
        s = S_fast(a)
        if s is None:
            return False
        if s == a:
            return True
        a = s
    return None

def v(p, n):
    """p-adic valuation of n."""
    if n == 0:
        return float('inf')
    c = 0
    while n % p == 0:
        c += 1
        n //= p
    return c

# Check characterization: valid iff v2(N) odd, v3(N) >= (v2(N)+1)/2, 5∤N
def predicted_valid(n):
    a = v(2, n)
    b = v(3, n)
    if a == 0 or b == 0:
        return False
    if a % 2 == 0:
        return False
    if b < (a + 1) // 2:
        return False
    if n % 5 == 0:
        return False
    return True

# Test on [6, 50000]
mismatches = []
for n in range(6, 50001):
    actual = check_seq(n)
    pred = predicted_valid(n)
    if actual != pred:
        mismatches.append((n, actual, pred))

print(f"Mismatches in [6, 50000]: {len(mismatches)}")
for n, act, pred in mismatches[:20]:
    a, b = v(2,n), v(3,n)
    print(f"  N={n}: actual={act}, predicted={pred}, v2={a}, v3={b}, 5|N={n%5==0}")

# Count valid
valid_count = sum(1 for n in range(6, 50001) if predicted_valid(n))
print(f"\nPredicted valid count in [6, 50000]: {valid_count}")

# Check some v2=7 cases
print("\nv2=7 cases (should be valid if v3>=4, 5∤N):")
for n in [2**7 * 3**4, 2**7 * 3**4 * 7, 2**7 * 3**3 * 7]:
    a, b = v(2,n), v(3,n)
    pred = predicted_valid(n)
    act = check_seq(n)
    print(f"  N={n}: v2={a}, v3={b}, 5|N={n%5==0}, predicted={pred}, actual={act}")
